package com.manishrawat.realestate.servlet;
import com.manishrawat.realestate.dao.ApplicationDAO; import com.manishrawat.realestate.model.User; import com.manishrawat.realestate.thread.NotificationWorker;
import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.*;
@WebServlet("/application") public class ApplicationServlet extends HttpServlet{
 private final ApplicationDAO dao=new ApplicationDAO();
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{User u=(User)r.getSession().getAttribute("user");r.setAttribute("applications","TENANT".equals(u.getRole())?dao.forTenant(u.getId()):"MANAGER".equals(u.getRole())?dao.forManager(u.getId()):dao.all());r.getRequestDispatcher("/WEB-INF/views/applications.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{User u=(User)r.getSession(false).getAttribute("user");String action=r.getParameter("action");if("apply".equals(action)){if(!"TENANT".equals(u.getRole())){s.sendError(403);return;}int pid=Integer.parseInt(r.getParameter("propertyId"));String message=r.getParameter("message");if(message!=null&&message.length()>4000)throw new IllegalArgumentException("Message is too long.");if(!dao.apply(pid,u.getId(),message==null?"":message.trim()))throw new IllegalArgumentException("This property is unavailable or you already applied.");int manager=dao.managerForProperty(pid);if(manager>0)NotificationWorker.submit(manager,"New rental application received.");}else{if(!"ADMIN".equals(u.getRole())&& !"MANAGER".equals(u.getRole())){s.sendError(403);return;}String status=r.getParameter("status");int tenant=dao.status(Integer.parseInt(r.getParameter("id")),status,"MANAGER".equals(u.getRole())?u.getId():null);NotificationWorker.submit(tenant,"Your rental application status was updated to "+status+".");}s.sendRedirect(r.getContextPath()+"/application?saved=1");}catch(IllegalArgumentException e){s.sendRedirect(r.getContextPath()+"/application?error=Invalid+application+request");}catch(Exception e){throw new IOException("Unable to save application. Please try again.",e);}}
}
